s=s.replace('스칸디나비안 프리미엄의 가치.<br>복잡한 정보는 쉽게, 필요한 내용은 정확하게 안내해드립니다.','모델 선택부터 트림 비교, 시승과 출고 이후까지.<br>필요한 정보만 쉽고 정확하게 안내해드립니다.')
s=s.replace('<div class="actions"><a class="btn light" href="#lineup">모델 라인업 살펴보기 →</a><button class="btn" onclick="alert(\'브랜드 영상은 다음 업데이트에서 연결됩니다.\')">▶ 브랜드 영상 보기</button></div>','<div class="actions"><a class="btn light" href="#lineup">내게 맞는 볼보 찾기</a><a class="btn" href="http://qr.kakao.com/talk/2LfLSm9DLJcfVv19vfXeS5R1AHQ-" target="_blank" rel="noopener">카카오톡 상담</a></div>')

profile='''<aside class="profile compact-profile" id="contact"><img src="assets/img03.webp" alt="이민웅 Sales Consultant"><div class="pb"><small>VOLVO SALES CONSULTANT</small><h3>이민웅</h3><p>차를 고르는 순간부터 출고 이후까지,<br>필요한 내용을 쉽고 정확하게 안내합니다.</p><div class="profile-actions"><a class="contact" href="tel:01026503211">전화 상담</a><a class="contact kakao" href="http://qr.kakao.com/talk/2LfLSm9DLJcfVv19vfXeS5R1AHQ-" target="_blank" rel="noopener">카카오톡</a></div></div></aside>'''
s=re.sub(r'<aside class="profile(?: compact-profile)?" id="contact">.*?</aside>',profile,s,count=1,flags=re.S)

category='''<div class="category-showcase" aria-label="볼보 바디타입 선택"><button class="category-card active" data-filter="suv" onclick="filterCategory('suv',this)"><span class="cat-kicker">VOLVO SUV</span><strong>SUV</strong><small>도심형 XC40부터 플래그십 XC90까지</small><span class="cat-arrow">차량 보기 →</span></button><button class="category-card" data-filter="electric" onclick="filterCategory('electric',this)"><span class="cat-kicker">PURE ELECTRIC</span><strong>ELECTRIC</strong><small>EX30 · EX90 · ES90, 전동화 라이프스타일</small><span class="cat-arrow">차량 보기 →</span></button><button class="category-card" data-filter="sedan" onclick="filterCategory('sedan',this)"><span class="cat-kicker">VOLVO SEDAN</span><strong>SEDAN</strong><small>정숙함과 편안함을 위한 S90</small><span class="cat-arrow">차량 보기 →</span></button></div><div class="model-list-head"><div><span>SELECTED MODELS</span><h3 id="selectedCategoryTitle">SUV 라인업</h3></div><button onclick="filterCategory('all',this)">전체 모델 보기</button></div>'''
if 'category-showcase' not in s:
    s=s.replace('<div class="models">',category+'<div class="models" id="modelGrid">',1)
elif 'id="modelGrid"' not in s:
    s=s.replace('<div class="models">','<div class="models" id="modelGrid">',1)

floating='''<div class="floating-contact" aria-label="빠른 상담"><div class="floating-person"><img src="assets/img03.webp" alt=""><span><b>이민웅</b><small>Volvo Sales Consultant</small></span></div><a href="tel:01026503211">전화 상담</a><a class="fkakao" href="http://qr.kakao.com/talk/2LfLSm9DLJcfVv19vfXeS5R1AHQ-" target="_blank" rel="noopener">카카오톡 상담</a></div>'''
