js='''<script id="premium-v5-js">function filterCategory(cat,button){const map={XC40:'suv',XC60:'suv',XC90:'suv',EX30:'electric',EX90:'electric',ES90:'electric',S90:'sedan'};document.querySelectorAll('.category-card').forEach(b=>b.classList.toggle('active',b.dataset.filter===cat));document.querySelectorAll('#modelGrid .model').forEach(card=>{const name=card.querySelector('h3')?.textContent.trim()||'';card.style.display=(cat==='all'||map[name]===cat)?'block':'none'});const title={suv:'SUV 라인업',electric:'순수 전기 라인업',sedan:'세단 라인업',all:'볼보 전 라인업'}[cat]||'볼보 라인업';const el=document.getElementById('selectedCategoryTitle');if(el)el.textContent=title}document.addEventListener('DOMContentLoaded',()=>filterCategory('suv',document.querySelector('.category-card[data-filter="suv"]')));</script>'''
s=re.sub(r'<script id="premium-v5-js">.*?</script>','',s,flags=re.S)
s=s.replace('</body>',js+'</body>',1)
